// This is a simple test to verify threshold parsing logic

function parseThresholds(thresholdArgs = []) {
  const thresholds = {};
  const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];

  for (const arg of thresholdArgs) {
    const match = arg.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      console.error(`Invalid threshold format: "${arg}". Expected format: <metric>=<number>`);
      process.exit(2);
    }

    const [, metric, valueStr] = match;
    const value = parseFloat(valueStr);

    if (isNaN(value) || value < 0 || value > 1) {
      console.error(`Invalid threshold value: "${valueStr}" for metric "${metric}". Value must be between 0 and 1.`);
      process.exit(2);
    }

    if (!validMetricIds.includes(metric)) {
      console.error(`Unknown metric: "${metric}". Valid metrics: ${validMetricIds.join(', ')}`);
      process.exit(2);
    }

    thresholds[metric] = value;
  }

  return thresholds;
}

// Test cases
console.log('Test 1: Valid threshold');
console.log(parseThresholds(['exact_match=0.9']));

console.log('\nTest 2: Multiple thresholds');
console.log(parseThresholds(['exact_match=0.9', 'toxicity=0.95']));

console.log('\nTest 3: Valid 0 and 1 values');
console.log(parseThresholds(['exact_match=0', 'toxicity=1']));

console.log('\nTest 4: Decimal values');
console.log(parseThresholds(['length_variance=0.5']));
EOF
